style.css:
@-moz-document domain("tumblr.com") {
/* =========================================================
     MEGURINE LUKA x LIGHT GREEN HOVER TUMBLR STYLISH CSS
     (Complete All-in-One Theme & Recolored Icons - No Images)
     ========================================================= */


  :root {
    --luka-bg-light: #fdf4f7;
    --luka-card: #ffffff;
    --luka-pink: #f4a4b8;
    --luka-rose: #d96b8a;
    --luka-gold: #e5c173;
    --luka-dark: #382a34;
    --hover-green: #7ed49e;
    --hover-mint-bg: #ebfaf0;
  }

  /* Custom Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: var(--luka-bg-light);
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--luka-pink), var(--luka-gold));
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--hover-green);
  }

  /* Text Selection */
  ::selection {
    background: var(--hover-green);
    color: #ffffff;
  }

  /* Pure CSS Polka-Dot Background */
  body {
    background-color: var(--luka-bg-light) !important;
    background-image: 
      radial-gradient(var(--luka-pink) 1.2px, transparent 1.2px),
      radial-gradient(var(--luka-gold) 1.2px, var(--luka-bg-light) 1.2px) !important;
    background-size: 36px 36px !important;
    background-position: 0 0, 18px 18px !important;
    font-family: 'Quicksand', sans-serif !important;
    color: var(--luka-dark) !important;
  }

  /* Dashboard & Main Containers */
  #base-container,
  .l-container,
  [data-testid="scroll-container"] {
    background: transparent !important;
  }

  /* Post Cards */
  article,
  .post,
  [data-id] > div {
    background: var(--luka-card) !important;
    border: 2px solid var(--luka-pink) !important;
    border-radius: 20px !important;
    box-shadow: 0 6px 18px rgba(217, 107, 138, 0.14) !important;
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease !important;
  }

  article:hover,
  .post:hover {
    transform: translateY(-2px);
    border-color: var(--hover-green) !important;
    box-shadow: 0 10px 24px rgba(126, 212, 158, 0.25) !important;
  }

  /* Links & Usernames (Light Green Hover) */
  a {
    color: var(--luka-rose) !important;
    transition: color 0.2s ease, text-shadow 0.2s ease !important;
  }

  a:hover {
    color: var(--hover-green) !important;
    text-shadow: 0 0 8px rgba(126, 212, 158, 0.4) !important;
  }

  /* Tags (Light Green Hover) */
  a[href*="/tagged/"] {
    background: #fff0f5 !important;
    border: 1px solid var(--luka-pink) !important;
    border-radius: 12px !important;
    padding: 2px 8px !important;
    font-size: 12px !important;
    color: var(--luka-rose) !important;
    display: inline-block;
    margin: 2px !important;
    transition: all 0.25s ease !important;
  }

  a[href*="/tagged/"]:hover {
    background: var(--hover-green) !important;
    border-color: var(--hover-green) !important;
    color: #ffffff !important;
  }

  /* Buttons (Follow, Reblog, Post) */
  button[aria-label*="Follow"],
  button[type="submit"],
  a[href="/new"],
  button[aria-label*="Create a post"] {
    background: linear-gradient(135deg, var(--luka-pink), var(--luka-rose)) !important;
    color: #ffffff !important;
    border-radius: 16px !important;
    border: none !important;
    font-weight: 700 !important;
    transition: all 0.25s ease !important;
  }

  button[aria-label*="Follow"]:hover,
  button[type="submit"]:hover,
  a[href="/new"]:hover,
  button[aria-label*="Create a post"]:hover {
    background: linear-gradient(135deg, #98e6b4, var(--hover-green)) !important;
    box-shadow: 0 4px 12px rgba(126, 212, 158, 0.4) !important;
    transform: translateY(-2px);
  }

  /* Avatar Frames */
  img[alt*="Avatar"],
  .avatar img {
    border-radius: 50% !important;
    border: 2px solid var(--luka-gold) !important;
    transition: border-color 0.25s ease !important;
  }

  img[alt*="Avatar"]:hover,
  .avatar img:hover {
    border-color: var(--hover-green) !important;
  }

  /* Blockquotes */
  blockquote {
    border-left: 3px solid var(--luka-gold) !important;
    background: #fff7fa !important;
    border-radius: 0 12px 12px 0 !important;
    padding: 8px 14px !important;
  }

  /* =========================================================
     NAVIGATION & POST FOOTER ICONS (LIGHT GREEN HOVER)
     ========================================================= */

  nav svg,
  header svg,
  aside svg,
  [role="navigation"] svg {
    fill: var(--luka-rose) !important;
    color: var(--luka-rose) !important;
    transition: transform 0.25s ease, fill 0.25s ease !important;
  }

  nav a:hover svg,
  header button:hover svg,
  aside a:hover svg {
    fill: var(--hover-green) !important;
    color: var(--hover-green) !important;
    transform: scale(1.15) rotate(-4deg);
  }

  article footer button svg,
  [data-testid="post-footer"] button svg {
    fill: var(--luka-pink) !important;
    color: var(--luka-pink) !important;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
  }

  article footer button,
  [data-testid="post-footer"] button {
    border-radius: 50% !important;
    padding: 6px !important;
    transition: background-color 0.2s ease !important;
  }

  article footer button:hover,
  [data-testid="post-footer"] button:hover {
    background-color: var(--hover-mint-bg) !important;
  }

  article footer button:hover svg,
  [data-testid="post-footer"] button:hover svg {
    fill: var(--hover-green) !important;
    color: var(--hover-green) !important;
    transform: scale(1.2);
  }
}
